def file_name_check(file_name):
    if len([char for char in file_name if char.isdigit()]) > 3:
        return 'No'

    if file_name.count('.') != 1:
        return 'No'

    segments = file_name.split('.')
    if not segments[0] or not segments[0][0].isalpha():
        return 'No'

    if segments[1] not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'
def check_numerical_digits(file_name):
    return sum(c.isdigit() for c in file_name) <= 3

def check_one_period(file_name):
    return file_name.count('.') == 1

def check_segment_before_period(file_name):
    segments = file_name.split('.')
    if len(segments) < 2:
        return False
    segment_before_period = segments[0]
    return segment_before_period and segment_before_period[0].isalpha()

def check_segment_after_period(file_name):
    segments = file_name.split('.')
    if len(segments) < 2:
        return False
